targets:
is_bigger_than :: proc(number: int, compare_to: int) -> bool {
	return number > compare_to
}

entry_map :: proc(level: int, result_set: int) -> bool {
	return level > result_set
}

data_store :: proc(value: int, count_total: int) -> bool {
	return value > count_total
}

result_set :: proc(count: int, total_sum: int) -> bool {
	return count > total_sum
}

count_total :: proc(total: int, score_list: int) -> bool {
	return total > score_list
}

total_sum :: proc(amount: int, item_data: int) -> bool {
	return amount > item_data
}

score_list :: proc(item: int, value_list: int) -> bool {
	return item > value_list
}

item_data :: proc(data: int, entry_map: int) -> bool {
	return data > entry_map
}
